using System;
using Xunit;
using ContosoUniversity.Services;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain the static queue to avoid cross-test contamination
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_CreatesNotificationWithCorrectMessage()
        {
            _service.SendNotification("Student", "1", "John", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("John", notification.Message);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_CreatesNotificationWithIdInMessage()
        {
            _service.SendNotification("Student", "42", EntityOperation.UPDATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_Delete_GeneratesDeleteMessage()
        {
            _service.SendNotification("Student", "1", "John", EntityOperation.DELETE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("deleted", notification.Message);
            Assert.Contains("John", notification.Message);
        }

        [Fact]
        public void SendNotification_DefaultOperation_GeneratesDefaultMessage()
        {
            _service.SendNotification("Student", "1", "John", (EntityOperation)99);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("operation:", notification.Message);
        }

        [Fact]
        public void SendNotification_SetsAllProperties()
        {
            var before = DateTime.Now;
            _service.SendNotification("Student", "5", "Jane", EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("5", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.True(notification.CreatedAt >= before && notification.CreatedAt <= DateTime.Now);
        }

        [Fact]
        public void SendNotification_WithUserName_SetsCreatedBy()
        {
            _service.SendNotification("Course", "10", EntityOperation.CREATE, "testuser");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("testuser", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _service.SendNotification("Course", "10", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_WhenQueueHasItems_ReturnsNotification()
