        [Fact]
        public void GetNotifications_WithNotifications_ReturnsThemAsJson()
        {
            DrainNotificationQueue();

            // Enqueue notifications via a separate NotificationService instance before creating the controller
            var svc = new NotificationService();
            svc.SendNotification("Student", "1", "John Smith", EntityOperation.CREATE);
            svc.SendNotification("Course", "101", "Math 101", EntityOperation.UPDATE);

            using var context = CreateContext();
            var controller = new NotificationsController(context);
            var result = controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
            dynamic data = result.Value;
            var type = result.Value.GetType();

            var successProp = type.GetProperty("success");
            Assert.True((bool)successProp.GetValue(result.Value));

            var notificationsProp = type.GetProperty("notifications");
            var notifications = (IList<Notification>)notificationsProp.GetValue(result.Value);
            Assert.Equal(2, notifications.Count);

            var countProp = type.GetProperty("count");
            Assert.Equal(2, (int)countProp.GetValue(result.Value));
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsEmptyList()
        {
            DrainNotificationQueue();

            using var context = CreateContext();
            var controller = new NotificationsController(context);
            var result = controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
            var type = result.Value.GetType();

            var successProp = type.GetProperty("success");
            Assert.True((bool)successProp.GetValue(result.Value));

            var countProp = type.GetProperty("count");
            Assert.Equal(0, (int)countProp.GetValue(result.Value));

            var notificationsProp = type.GetProperty("notifications");
            var notifications = (IList<Notification>)notificationsProp.GetValue(result.Value);
            Assert.Empty(notifications);
        }

        [Fact]
        public void GetNotifications_LimitsTo10()
        {
            DrainNotificationQueue();

            // Enqueue 15 notifications before creating controller
            var svc = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Student", i.ToString(), $"Student {i}", EntityOperation.CREATE);
            }

            using var context = CreateContext();
            var controller = new NotificationsController(context);
            var result = controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
            var type = result.Value.GetType();

            var countProp = type.GetProperty("count");
            Assert.Equal(10, (int)countProp.GetValue(result.Value));

            var notificationsProp = type.GetProperty("notifications");
            var notifications = (IList<Notification>)notificationsProp.GetValue(result.Value);
            Assert.Equal(10, notifications.Count);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            DrainNotificationQueue();

            using var context = CreateContext();
            var controller = new NotificationsController(context);
            var result = controller.MarkAsRead(1);

            Assert.IsType<JsonResult>(result);
            var type = result.Value.GetType();

            var successProp = type.GetProperty("success");
            Assert.True((bool)successProp.GetValue(result.Value));
        }

