using Xunit;
using Moq;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Hosting;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests
    {
        private SchoolContext CreateContext()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        private CoursesController CreateController(SchoolContext context)
        {
            var mockEnv = new Mock<IWebHostEnvironment>();
            mockEnv.Setup(e => e.WebRootPath).Returns((string)null);
            mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
            var mockLogger = new Mock<ILogger<CoursesController>>();
            return new CoursesController(context, mockEnv.Object, mockLogger.Object);
        }

        private Department SeedDepartment(SchoolContext context, string name = "Engineering")
        {
            var dept = new Department
            {
                Name = name,
                Budget = 100000m,
                StartDate = DateTime.Today,
                RowVersion = new byte[] { 1 }
            };
            context.Departments.Add(dept);
            context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(SchoolContext context, int courseId, string title, int departmentId)
        {
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = 3,
                DepartmentID = departmentId
            };
            context.Courses.Add(course);
            context.SaveChanges();
            return course;
        }

        [Fact]
        public void Index_ReturnsAllCourses()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            SeedCourse(context, 1001, "Calculus", dept.DepartmentID);
            SeedCourse(context, 1002, "Physics", dept.DepartmentID);

            var controller = CreateController(context);
            var result = controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Details_ValidId_ReturnsCourse()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            var course = SeedCourse(context, 2001, "Chemistry", dept.DepartmentID);

            var controller = CreateController(context);
            var result = controller.Details(2001);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);

            var result = controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Create_Get_SetsViewBagDepartmentID()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            SeedDepartment(context, "Math");
            var controller = CreateController(context);

            var result = controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.NotNull(controller.ViewBag.DepartmentID);
            Assert.IsType<SelectList>(controller.ViewBag.DepartmentID);
        }

        [Fact]
        public void Create_Post_ValidCourse_NoFile_SavesAndRedirects()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course
            {
                CourseID = 3001,
                Title = "Biology",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };

            var result = controller.Create(course, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(context.Courses);
            Assert.Equal("Biology", context.Courses.First().Title);
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            SeedDepartment(context);
            var controller = CreateController(context);
            controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 3002, Credits = 3, DepartmentID = 1 };

            var result = controller.Create(course, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Course>(viewResult.Model);
        }

        [Fact]
        public void Create_Post_InvalidFileExtension_AddsModelError()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course
            {
                CourseID = 3003,
                Title = "Art",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            var result = controller.Create(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("valid image file", controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage);
        }

        [Fact]
        public void Create_Post_FileTooLarge_AddsModelError()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course
            {
                CourseID = 3004,
                Title = "Music",
                Credits = 1,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024L);

            var result = controller.Create(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("5MB", controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsCourse()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            SeedCourse(context, 4001, "History", dept.DepartmentID);
            var controller = CreateController(context);

            var result = controller.Edit(4001);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("History", model.Title);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);

            var result = controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_MissingCourse_ReturnsNotFound()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);

            var result = controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsCourse()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            SeedCourse(context, 5001, "Geography", dept.DepartmentID);
            var controller = CreateController(context);

            var result = controller.Delete(5001);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Geography", model.Title);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);

            var result = controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void DeleteConfirmed_DeletesCourseAndRedirects()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            SeedCourse(context, 6001, "Literature", dept.DepartmentID);
            var controller = CreateController(context);

            var result = controller.DeleteConfirmed(6001);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(context.Courses);
        }
    }
}

