            var result = controller.Create(course, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Course>(viewResult.Model);
        }

        [Fact]
        public void Create_Post_InvalidFileExtension_AddsModelError()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course
            {
                CourseID = 3003,
                Title = "Art",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            var result = controller.Create(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("valid image file", controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage);
        }

        [Fact]
        public void Create_Post_FileTooLarge_AddsModelError()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course
            {
                CourseID = 3004,
                Title = "Music",
                Credits = 1,
                DepartmentID = dept.DepartmentID
            };
