using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests
    {
        private SchoolContext CreateContext()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        private DepartmentsController CreateController(SchoolContext context)
        {
            return new DepartmentsController(context);
        }

        private Department MakeDepartment(string name = "Engineering", decimal budget = 100000m)
        {
            return new Department
            {
                Name = name,
                Budget = budget,
                StartDate = DateTime.Today,
                RowVersion = new byte[] { 1 }
            };
        }

        private Department SeedDepartment(SchoolContext context, string name = "Engineering", decimal budget = 100000m)
        {
            var dept = MakeDepartment(name, budget);
            context.Departments.Add(dept);
            context.SaveChanges();
            return dept;
        }

        private Instructor SeedInstructor(SchoolContext context, string last = "Smith", string first = "John")
        {
            var instructor = new Instructor
            {
                LastName = last,
                FirstMidName = first,
                HireDate = DateTime.Today
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();
            return instructor;
        }

        [Fact]
        public void Index_ReturnsAllDepartments()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            SeedDepartment(context, "Math");
            SeedDepartment(context, "Science");

            var controller = CreateController(context);
            var result = controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Details_ValidId_ReturnsDepartment()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context, "Physics");

            var controller = CreateController(context);
            var result = controller.Details(dept.DepartmentID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Department>(viewResult.Model);
            Assert.Equal("Physics", model.Name);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);

            var result = controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_MissingDepartment_ReturnsNotFound()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);

            var result = controller.Details(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Create_Get_SetsViewBagInstructorID()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            SeedInstructor(context, "Doe", "Jane");
            var controller = CreateController(context);

            var result = controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.NotNull(controller.ViewBag.InstructorID);
            Assert.IsType<SelectList>(controller.ViewBag.InstructorID);
        }

        [Fact]
        public void Create_Post_ValidDepartment_SavesAndRedirects()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);
            var department = MakeDepartment("Chemistry", 50000m);

            var result = controller.Create(department);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(context.Departments);
            Assert.Equal("Chemistry", context.Departments.First().Name);
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);
            controller.ModelState.AddModelError("Name", "Required");
