        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);

            var result = controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Post_ValidDepartment_SavesAndRedirects()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context, "History");

            // Detach the tracked entity so the Edit POST can attach it as Modified
            context.Entry(dept).State = EntityState.Detached;

            var controller = CreateController(context);
            var updated = new Department
            {
                DepartmentID = dept.DepartmentID,
                Name = "Modern History",
                Budget = dept.Budget,
                StartDate = dept.StartDate,
                RowVersion = dept.RowVersion
            };

            var result = controller.Edit(updated);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsDepartment()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context, "Art");

            var controller = CreateController(context);
            var result = controller.Delete(dept.DepartmentID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Department>(viewResult.Model);
            Assert.Equal("Art", model.Name);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);

            var result = controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_MissingDepartment_ReturnsNotFound()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var controller = CreateController(context);

            var result = controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void DeleteConfirmed_DeletesAndRedirects()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context, "Music");

            var controller = CreateController(context);
            var result = controller.DeleteConfirmed(dept.DepartmentID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(context.Departments);
        }
    }
}

