                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        private InstructorsController CreateController(SchoolContext context)
        {
            return new InstructorsController(context);
        }

        private Instructor SeedInstructor(SchoolContext context, string lastName = "Smith", string firstName = "John")
        {
            var instructor = new Instructor
            {
                LastName = lastName,
                FirstMidName = firstName,
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = null
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();
            return instructor;
        }

        private Department SeedDepartment(SchoolContext context, string name = "Engineering", int? instructorId = null)
        {
            var dept = new Department
            {
                Name = name,
                Budget = 100000m,
                StartDate = DateTime.Today,
                InstructorID = instructorId
            };
            context.Departments.Add(dept);
            context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(SchoolContext context, int courseId, string title, int departmentId)
        {
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = 3,
                DepartmentID = departmentId
            };
            context.Courses.Add(course);
            context.SaveChanges();
            return course;
        }

        [Fact]
        public void Index_NoSelection_ReturnsAllInstructors()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            SeedInstructor(context, "Smith", "John");
            SeedInstructor(context, "Jones", "Jane");

            var controller = CreateController(context);
            var result = controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_SelectsInstructorCourses()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            var course = SeedCourse(context, 1050, "Test Course", dept.DepartmentID);

            var instructor = SeedInstructor(context);
            context.CourseAssignments.Add(new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID });
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Index(instructor.ID, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.Single(model.Courses);
            Assert.Equal("Test Course", model.Courses.First().Title);
        }

        [Fact]
        public void Index_WithCourseId_SelectsEnrollments()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            var course = SeedCourse(context, 1050, "Test Course", dept.DepartmentID);

            var instructor = SeedInstructor(context);
            context.CourseAssignments.Add(new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID });
            context.SaveChanges();

            var student = new Student { LastName = "Doe", FirstMidName = "Jane", EnrollmentDate = DateTime.Now };
            context.Students.Add(student);
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment { CourseID = course.CourseID, StudentID = student.ID, Grade = Grade.A });
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Index(instructor.ID, course.CourseID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.Single(model.Enrollments);
        }

        [Fact]
        public void Details_ValidId_ReturnsInstructor()
        {
            DrainNotificationQueue();
