        [Fact]
        public void DeleteConfirmed_DeletesCourseAndRedirects()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            SeedCourse(context, 6001, "Literature", dept.DepartmentID);
            var controller = CreateController(context);

            var result = controller.DeleteConfirmed(6001);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(context.Courses);
        }

        [Fact]
        public void Edit_Post_InvalidFileExtension_AddsModelError()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            SeedCourse(context, 7001, "History", dept.DepartmentID);
            var controller = CreateController(context);

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            var course = new Course { CourseID = 7001, Title = "History", Credits = 3, DepartmentID = dept.DepartmentID };

            var result = controller.Edit(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.False(controller.ModelState.IsValid);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_FileTooLarge_AddsModelError()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            SeedCourse(context, 7002, "Philosophy", dept.DepartmentID);
            var controller = CreateController(context);

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024L);

            var course = new Course { CourseID = 7002, Title = "Philosophy", Credits = 3, DepartmentID = dept.DepartmentID };

            var result = controller.Edit(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.False(controller.ModelState.IsValid);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_FileExactly5MB_IsAccepted()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(5 * 1024 * 1024L); // exactly 5MB
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var course = new Course { CourseID = 7003, Title = "Art", Credits = 3, DepartmentID = dept.DepartmentID };

            var result = controller.Create(course, mockFile.Object);

            // 5MB should be accepted (the check is > 5MB, not >=)
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_ValidCourse_NoFile_SavesAndRedirects()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            var dept = SeedDepartment(context);
            SeedCourse(context, 7004, "Biology", dept.DepartmentID);
            var controller = CreateController(context);

            // Detach the existing entity first
            var existing = context.Courses.Find(7004);
            context.Entry(existing).State = EntityState.Detached;

            var course = new Course { CourseID = 7004, Title = "Biology Updated", Credits = 4, DepartmentID = dept.DepartmentID };

            var result = controller.Edit(course, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = context.Courses.Find(7004);
            Assert.Equal("Biology Updated", saved.Title);
        }

        [Fact]
        public void Create_Post_InvalidModel_SetsViewBagDepartmentID()
        {
            DrainNotificationQueue();
            using var context = CreateContext();
            SeedDepartment(context);
            var controller = CreateController(context);
            controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 8001, Credits = 3 };

            var result = controller.Create(course, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.NotNull(controller.ViewBag.DepartmentID);
        }
    }
}

